+  # `a |> f(args)` → `f(a, args)`; `a |> f` / `a |> M.f` → `f(a)` (bare callee).
+  defp pipe_into(l, {:call, fun, args}), do: {:call, fun, [l | args]}
+  defp pipe_into(l, callee), do: {:call, callee, [l]}
